import base64
import itertools
import string

# 1. Read base64 ciphertext from file
with open('/home/ctfplayer/ctf_files/ciphertext.txt','r') as f:
    b64 = f.read().strip()

# 2. Decode base64 ciphertext to bytes
data = base64.b64decode(b64)

# Util - xor with repeating key
def xor_repeat(data, key):
    rk = (key * (len(data)//len(key)+1))[:len(data)]
    return bytes([b ^ k for b,k in zip(data, rk)])

# Store findings
found = []

# 3a. Single-byte key
for k in range(256):
    pt = xor_repeat(data, bytes([k]))
    if b'flag{' in pt:
        found.append((bytes([k]), pt))

# 3b. 2- and 3-printable-char ASCII keys
printable_chars = [c.encode() for c in string.printable if c not in '\r\n\t']
for keylen in [2,3]:
    for key_tuple in itertools.product(printable_chars, repeat=keylen):
        key = b''.join(key_tuple)
        pt = xor_repeat(data, key)
        if b'flag{' in pt:
            found.append((key, pt))
            break # Save time if found
    if found:
        break

# 3c. Various cases of 'yeet'
yeet_cases = ['yeet','YEET','Yeet','yEeT','yeEt','yeEt','yeEt'.upper(),'yeEt'.capitalize()]
for candidate in set(yeet_cases):
    key = candidate.encode()
    pt = xor_repeat(data, key)
    if b'flag{' in pt:
        found.append((key, pt))

# 4. Print findings
if found:
    for key, pt in found:
        try:
            pt_dec = pt.decode('utf-8')
        except:
            pt_dec = repr(pt)
        print(f"[+] Key: {key} => {pt_dec}")
else:
    # fallback: print best guess
    best_score = -9999
    best = None
    # Use heuristics: number of printable chars
    for k in range(256):
        pt = xor_repeat(data, bytes([k]))
        sc = sum([32 <= b <= 126 for b in pt])
        if sc > best_score:
            best_score = sc
            best = (bytes([k]), pt)
    try:
        pt_dec = best[1].decode('utf-8')
    except:
        pt_dec = repr(best[1])
    print(f'Most human-readable candidate, key={best[0]}: {pt_dec}')

